<?php get_header(); $author = get_queried_object(); ?>
<header class="bsw-archive-header"><p class="bsw-eyebrow">BIGSHOR COMMUNITY</p><h1 class="page-title">Articles by <?php echo esc_html( get_the_author_meta( 'display_name', $author->ID ) ); ?></h1><?php $bio = get_the_author_meta( 'description', $author->ID ); if ( $bio ) : ?><p class="bsw-article-deck"><?php echo esc_html( $bio ); ?></p><?php endif; ?></header>
<?php if ( have_posts() ) : ?><ul class="wiki-list bsw-author-list"><?php while ( have_posts() ) : the_post(); ?><li><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div class="wiki-meta">Updated <?php echo esc_html( get_the_modified_date() ); ?></div><?php the_excerpt(); ?></li><?php endwhile; ?></ul><nav class="pagination" aria-label="Author article pagination"><?php the_posts_pagination(); ?></nav><?php else : ?><p>No published articles found for this contributor.</p><?php endif; ?><?php get_footer();
